                // Si no hay ninguno, es un error de arranque → re-arrancar
                // la fase actual desde cero (no hay estado que preservar).
                setConnectionError(null);
                const hasUserTurn = conversationHistoryRef.current.some((m) => m.role === "user");
                if (hasUserTurn) {
