function ReplicaChat({
  worldId,
  nodeId,
  sessionId,
  practiceScript,
  evaluation,
  conversation,
  companyId,
  sellerId,
}: {
  worldId: number;
  nodeId: string;
  sessionId: string;
  practiceScript: any;
  evaluation: any;
  conversation: { role: string; content: string }[];
  companyId?: string | null;
  sellerId?: string | null;
}) {
  const [open, setOpen] = useState(false);
  const [thread, setThread] = useState<{ role: "user" | "assistant"; content: string }[]>([]);
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const userTurns = thread.filter((m) => m.role === "user").length;
  const limitReached = userTurns >= 3;

  if (worldId === 9) return null;

  async function send() {
    const msg = draft.trim();
    if (!msg || sending || limitReached) return;
    setSending(true);
    setError(null);
    const priorThread = thread;
    const nextThreadOptimistic = [...priorThread, { role: "user" as const, content: msg }];
    setThread(nextThreadOptimistic);
    setDraft("");
    try {
      const accessToken = await llaveUsuario();
      // Un tropiezo pasajero no debe obligar al vendedor a reescribir su
      // desacuerdo: se reintenta solo, una vez.
      const pedir = () => fetchFuncion(`${SUPABASE_URL}/functions/v1/closer-voice`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_ANON,
          Authorization: `Bearer ${accessToken}`,
        },
        body: JSON.stringify({
          phase: "replica",
          node_id: nodeId,
          practice_script: practiceScript,
          original_evaluation: evaluation,
          conversation_history: conversation,
          replica_thread: priorThread,
          user_message: msg,
          session_id: sessionId,
          company_id: companyId ?? null,
          seller_id: sellerId ?? null,
        }),
      });
      let res = await pedir();
      if (!res.ok && res.status >= 500) {
        await new Promise((r) => setTimeout(r, 1200));
        res = await pedir();
      }
      const raw = await res.text();
      if (!res.ok) throw new Error(`replica HTTP ${res.status}: ${raw.slice(0, 200)}`);
      const parsed = JSON.parse(raw) as { message?: string };
      const reply = typeof parsed.message === "string" ? parsed.message : "";
      if (!reply) throw new Error("respuesta vacía");
      setThread([...nextThreadOptimistic, { role: "assistant", content: reply }]);

      // Persist exchange as seller_event
      try {
        const form = new FormData();
        form.append(
          "meta",
          JSON.stringify({
            event_type: "evaluation_replica",
            node_id: nodeId,
            session_id: sessionId,
            payload: {
              session_id: sessionId,
              node_id: nodeId,
              turn_number: userTurns + 1,
              user_message: msg,
              closer_response: reply,
              original_score: evaluation?.score ?? null,
            },
          }),
        );
        await fetch(`${SUPABASE_URL}/functions/v1/save-practice-event`, {
          method: "POST",
          headers: {
            apikey: SUPABASE_ANON,
            Authorization: `Bearer ${accessToken || (await llaveUsuario())}`,
          },
          body: form,
        });
      } catch (e) {
        console.error("[replica] save-practice-event failed:", e);
      }
    } catch (e: any) {
      console.error("[replica] failed:", e);
      setThread(priorThread);
      setDraft(msg);
      setError("No pude responder ahora. Intenta de nuevo.");
    } finally {
      setSending(false);
    }
  }

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        style={{
          width: "100%",
          padding: "10px 14px",
          marginTop: 4,
          borderRadius: 99,
          border: "1px solid rgba(255,255,255,0.15)",
          background: "transparent",
          color: "rgba(255,255,255,0.7)",
          fontFamily: "'DM Sans', sans-serif",
          fontSize: 13,
          cursor: "pointer",
        }}
      >
        No estoy de acuerdo con mi evaluación
      </button>
    );
  }

  return (
    <div
      style={{
        width: "100%",
        marginTop: 4,
        padding: 14,
        borderRadius: 14,
        background: "rgba(255,255,255,0.04)",
        border: "1px solid rgba(255,255,255,0.10)",
        display: "flex",
        flexDirection: "column",
        gap: 10,
      }}
    >
      <div
        style={{
          fontFamily: "Syne, sans-serif",
          fontWeight: 700,
          fontSize: 13,
          color: "#fff",
          textTransform: "uppercase",
          letterSpacing: 0.6,
        }}
      >
        Tu réplica
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {thread.map((m, i) => (
          <div
            key={i}
            style={{
              alignSelf: m.role === "user" ? "flex-end" : "flex-start",
              maxWidth: "88%",
              padding: "10px 12px",
              borderRadius: 12,
              background:
                m.role === "user" ? "rgb(var(--c-primary-rgb) / 0.18)" : "rgba(255,255,255,0.06)",
              color: "#fff",
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 14,
              lineHeight: 1.45,
              whiteSpace: "pre-wrap",
            }}
          >
            {m.content}
          </div>
        ))}
        {sending && (
          <div
            style={{
              alignSelf: "flex-start",
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 12,
              color: "rgba(255,255,255,0.5)",
              fontStyle: "italic",
            }}
          >
            Closer está respondiendo…
          </div>
        )}
      </div>

      {error && (
        <div
          style={{
            fontFamily: "'DM Sans', sans-serif",
            fontSize: 12,
            color: "rgb(var(--c-danger-rgb) / 0.9)",
          }}
        >
          {error}
        </div>
      )}

      {limitReached ? (
        <div
          style={{
            fontFamily: "'DM Sans', sans-serif",
            fontSize: 13,
            lineHeight: 1.5,
            color: "rgba(255,255,255,0.65)",
            fontStyle: "italic",
          }}
        >
          Tu comentario quedó registrado — el equipo revisa estos casos para mejorar el entrenamiento.
        </div>
      ) : (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            send();
          }}
          style={{ display: "flex", gap: 8 }}
        >
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder={
              userTurns === 0
                ? "Explica por qué no estás de acuerdo…"
                : `Mensaje ${userTurns + 1} de 3`
            }
            disabled={sending}
            style={{
              flex: 1,
              height: 40,
              borderRadius: 99,
              border: "1px solid rgba(255,255,255,0.15)",
              background: "rgba(0,0,0,0.3)",
              padding: "0 14px",
              color: "#fff",
              fontFamily: "'DM Sans', sans-serif",
              fontSize: 14,
              outline: "none",
            }}
          />
          <button
            type="submit"
            disabled={!draft.trim() || sending}
            style={{
              height: 40,
              padding: "0 16px",
              borderRadius: 99,
              border: "none",
              background: ORANGE,
              color: "var(--c-bg)",
              fontFamily: "Syne, sans-serif",
              fontWeight: 700,
              fontSize: 13,
              cursor: draft.trim() && !sending ? "pointer" : "not-allowed",
              opacity: draft.trim() && !sending ? 1 : 0.5,
            }}
          >
            Enviar
          </button>
        </form>
      )}
    </div>
  );
}

function FeedbackPhase({
  nombresCriterio,
  closerMsgs,
  onContinue,
  onLeaveWithoutEval,
  conversation,
  feedback,
  worldId,
  nodeId,
  sessionId,
  practiceScript,
  evaluation,
  companyId,
  sellerId,
  evalError,
  onRetryEvaluation,
}: {
  nombresCriterio?: Record<string, string>;
  closerMsgs: Set<string>;
  onContinue: (stars: 0 | 1 | 2 | 3) => void;
  /** Salir sin evaluación: no guarda estrellas, solo devuelve al mapa. */
  onLeaveWithoutEval: () => void;
  conversation: { role: string; content: string }[];
  feedback: FeedbackResult | null;
  worldId: number;
  nodeId: string;
  sessionId: string;
  practiceScript: any;
  evaluation: any;
  companyId?: string | null;
  sellerId?: string | null;
  evalError?: string | null;
  onRetryEvaluation?: () => void;
}) {
  const [step, setStep] = useState<FeedbackStep>("analyzing");
  const [msgIdx, setMsgIdx] = useState(0);
  const mensajes = mensajesDeAnalisis(practiceScript, nombresCriterio ?? {});
  const [slowNotice, setSlowNotice] = useState(false);

  useEffect(() => {
    if (feedback !== null) {
      setStep("result");
    }
  }, [feedback]);

  // Salida por error: si el evaluador falla o se pasa del timeout.
  useEffect(() => {
    if (evalError) setStep("eval_error");
  }, [evalError]);

  // Reintento: volvemos a la animación.
  useEffect(() => {
    if (!evalError && feedback === null && step === "eval_error") setStep("analyzing");
  }, [evalError, feedback, step]);

  // A los 25 s, aviso honesto: un análisis completo puede tardar más de un minuto.
  useEffect(() => {
    if (step !== "analyzing") {
      setSlowNotice(false);
      return;
    }
    setSlowNotice(false);
    const t = setTimeout(() => setSlowNotice(true), 25_000);
    return () => clearTimeout(t);
  }, [step]);

  useEffect(() => {
    if (step !== "analyzing") return;
    const i = setInterval(() => {
      setMsgIdx((p) => Math.min(p + 1, mensajes.length - 1));
    }, 2000);
    return () => clearInterval(i);
  }, [step]);


  const score = feedback?.score ?? 0;
  const stars: 0 | 1 | 2 | 3 = feedback?.stars ?? 0;
  const observations = feedback?.observations ?? [];
  const fallas = feedback?.fallas ?? [];

  if (step === "victory") {
    // Sin estrella no hay festejo: una pantalla neutra, sin confeti. La
    // estrella que ya se tenía no se pierde (el guardado toma el máximo).
    if (stars === 0) {
      return (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 24, textAlign: "center" }}>
          <div style={{ fontFamily: "Syne, sans-serif", fontWeight: 800, fontSize: 24, color: "var(--c-text)", marginBottom: 10 }}>Esta vez no salió.</div>
          <div style={{ fontFamily: "DM Sans, sans-serif", fontSize: 15, color: "rgb(var(--c-text-rgb) / 0.7)", maxWidth: 360, lineHeight: 1.5, marginBottom: 24 }}>
            No ganaste estrella en este intento, y las que ya tenías se conservan. Repite el nodo cuando quieras.
          </div>
          <button onClick={() => onContinue(0)} style={{ background: "var(--c-primary)", color: "var(--c-bg)", fontFamily: "Syne, sans-serif", fontWeight: 700, fontSize: 15, border: "none", borderRadius: 99, padding: "14px 28px", cursor: "pointer" }}>Volver al mapa →</button>
        </motion.div>
      );
    }
    return (
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ flex: 1, minHeight: 0 }}>
        <VictoryScreen
          stars={stars}
          title={stars >= 2 ? "¡Práctica completada!" : "Práctica registrada."}
          subtitle={
            stars >= 2
              ? "Sigue avanzando."
              : "Con 2 estrellas se abre el siguiente nodo. Repite este cuando quieras."
          }
          buttonText="Volver al mapa →"
          onContinue={() => onContinue(stars)}
        />
      </motion.div>
    );
  }

  if (step === "result") {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        style={{
          flex: 1,
          minHeight: 0,
          display: "flex",
          flexDirection: "column",
          padding: "1.2rem",
          overflowY: "auto",
        }}
      >
        <div
          style={{
            maxWidth: 560,
            width: "100%",
            margin: "0 auto",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 20,
            paddingTop: 16,
            paddingBottom: 24,
          }}
        >
          <CloserCharacter size={86} state="motivation" />
          <div
            style={{
              fontFamily: "Syne, sans-serif",
              fontWeight: 800,
              fontSize: 26,
              color: "#fff",
              textAlign: "center",
            }}
          >
            Tu práctica
          </div>

          {/* Score */}
          <div
            style={{
              width: "100%",
              padding: "20px 18px",
              borderRadius: 14,
              background: "rgb(var(--c-primary-rgb) / 0.10)",
              border: `1px solid color-mix(in srgb, ${ORANGE} 33%, transparent)`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 4,
            }}
          >
            <div
              style={{
                fontFamily: "'DM Sans', sans-serif",
                fontSize: 12,
                letterSpacing: 1,
                textTransform: "uppercase",
                color: "rgba(255,255,255,0.6)",
              }}
            >
              Score
            </div>
            <div
              style={{
                fontFamily: "Syne, sans-serif",
                fontWeight: 800,
                fontSize: 48,
                color: ORANGE,
                lineHeight: 1,
              }}
            >
              {score}
            </div>
          </div>

          {/* Lo que te bajó la nota: va primero. Disputa 3.10 (oct-2026): una
              falla crítica dejó la nota en 30 y la pantalla no la mencionaba. */}
          {fallas.length > 0 && (
            <div
              style={{
                width: "100%",
                padding: 16,
                borderRadius: 14,
                background: "rgb(var(--c-danger-rgb) / 0.08)",
                border: "1px solid rgb(var(--c-danger-rgb) / 0.35)",
                display: "flex",
                flexDirection: "column",
                gap: 12,
              }}
            >
              <div style={{ fontFamily: "Syne, sans-serif", fontWeight: 700, fontSize: 14, color: "#fff" }}>
                Lo que te bajó la nota
              </div>
              {fallas.map((f, i) => (
                <FallaCard key={i} falla={f} />
              ))}
            </div>
          )}

          {/* Observaciones */}
          {(observations.length > 0 || fallas.length === 0) && (
          <div
            style={{
              width: "100%",
              padding: 16,
              borderRadius: 14,
              background: "rgba(255,255,255,0.04)",
              border: "1px solid rgba(255,255,255,0.08)",
              display: "flex",
              flexDirection: "column",
              gap: 10,
            }}
          >
            <div
              style={{
                fontFamily: "Syne, sans-serif",
                fontWeight: 700,
                fontSize: 14,
                color: "#fff",
              }}
            >
{observations.length === 0 ? (score >= 85 ? "Ejecución limpia" : "Sesión incompleta") : "Observaciones de Closer"}
            </div>
{observations.length === 0 ? (
              // Cero observaciones NO es un fallo: es que ejecutó bien todos los
              // criterios de este nodo. Antes esto se pintaba como error.
              <div
                style={{
                  fontFamily: "'DM Sans', sans-serif",
                  fontSize: 14,
                  lineHeight: 1.5,
                  color: "rgba(255,255,255,0.8)",
                }}
              >
                {score >= 85
                  ? "Cumpliste todo lo que este nodo mide. No hay nada que corregir aquí."
                  : "La práctica terminó antes de que se viera lo que este nodo mide. Vuelve a intentarlo: esta nota no refleja lo que sabes."}
              </div>
            ) : (
              observations.map((o, i) => (
                <ObservationCard key={i} obs={o} />
              ))
            )}
          </div>
          )}

          {Array.isArray((feedback as any)?.siguiente_nivel) &&
            (feedback as any).siguiente_nivel.length > 0 && (
              <div
                style={{
                  width: "100%",
                  padding: 16,
                  borderRadius: 14,
                  background: "rgb(var(--c-client-rgb) / 0.08)",
                  border: "1px solid rgb(var(--c-client-rgb) / 0.35)",
                  display: "flex",
                  flexDirection: "column",
                  gap: 10,
                }}
              >
                <div
                  style={{
                    fontFamily: "Syne, sans-serif",
                    fontWeight: 800,
                    fontSize: 13,
                    color: "rgb(var(--c-client-rgb) / 0.95)",
                    textTransform: "uppercase",
                    letterSpacing: 0.8,
                  }}
                >
                  Lo que viene después
                </div>
                <div
                  style={{
                    fontFamily: "'DM Sans', sans-serif",
                    fontSize: 12,
                    color: "rgba(255,255,255,0.5)",
                  }}
                >
                  Esto no cuenta en tu calificación. Es lo que sigue cuando domines este nodo.
                </div>
                {(feedback as any).siguiente_nivel.map((x: any, i: number) => (
                  <div key={i} style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    <div
                      style={{
                        fontFamily: "'DM Sans', sans-serif",
                        fontSize: 14,
                        lineHeight: 1.5,
                        color: "#fff",
                      }}
                    >
                      {x.observacion}
                    </div>
                    {x.ejemplo ? (
                      <div
                        style={{
                          fontFamily: "'DM Sans', sans-serif",
                          fontSize: 13,
                          lineHeight: 1.5,
                          color: "rgba(255,255,255,0.6)",
                          fontStyle: "italic",
                        }}
                      >
                        {x.ejemplo}
                      </div>
                    ) : null}
                    {x.por_que ? (
                      <div
                        style={{
                          fontFamily: "'DM Sans', sans-serif",
                          fontSize: 12,
                          color: "rgb(var(--c-client-rgb) / 0.75)",
                        }}
                      >
                        {x.por_que}
                      </div>
                    ) : null}
                  </div>
                ))}
              </div>
            )}

          {feedback?.mision && (
            <div
              style={{
                width: "100%",
                padding: 16,
                borderRadius: 14,
                background: "rgb(var(--c-primary-rgb) / 0.10)",
                border: `1px solid ${ORANGE}`,
                display: "flex",
                flexDirection: "column",
                gap: 8,
              }}
            >
              <div
                style={{
                  fontFamily: "Syne, sans-serif",
                  fontWeight: 800,
                  fontSize: 14,
                  color: ORANGE,
                  textTransform: "uppercase",
                  letterSpacing: 0.8,
                }}
              >
                Tu misión
              </div>
              <div
                style={{
                  fontFamily: "'DM Sans', sans-serif",
                  fontSize: 15,
                  lineHeight: 1.5,
                  color: "#fff",
                }}
              >
                {feedback.mision}
              </div>
            </div>
          )}

          {feedback?.radarLines && feedback.radarLines.length > 0 && (
            <div
              style={{
                width: "100%",
                display: "flex",
                flexDirection: "column",
                gap: 6,
                padding: "10px 4px 0 4px",
              }}
            >
              {feedback.radarLines.map((line, i) => (
                <div
                  key={i}
                  style={{
                    fontFamily: "'DM Sans', sans-serif",
                    fontSize: 12,
                    lineHeight: 1.5,
                    color: "rgba(255,255,255,0.55)",
                    fontStyle: "italic",
                  }}
                >
                  {line}
                </div>
              ))}
            </div>
          )}

          <ConversationTranscript conversation={conversation} closerMsgs={closerMsgs} />

          {worldId !== 9 && evaluation && (
            <ReplicaChat
              worldId={worldId}
              nodeId={nodeId}
              sessionId={sessionId}
              practiceScript={practiceScript}
              evaluation={evaluation}
              conversation={conversation}
              companyId={companyId}
              sellerId={sellerId}
            />
          )}




          <button
            onClick={() => setStep("victory")}
            style={{
              width: "100%",
              height: 52,
              marginTop: 8,
              borderRadius: 99,
              border: "none",
              background: ORANGE,
              color: "var(--c-bg)",
              fontFamily: "Syne, sans-serif",
              fontWeight: 700,
              fontSize: 16,
              cursor: "pointer",
              boxShadow: "0 10px 30px -8px rgb(var(--c-primary-rgb) / 0.45)",
            }}
          >
            Ver resultado →
          </button>
        </div>
      </motion.div>
    );
  }

  if (step === "eval_error") {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        style={{
          flex: 1,
          minHeight: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 18,
          padding: "1.2rem",
        }}
      >
        <CloserCharacter size={86} state="motivation" />
        <div
          style={{
            fontFamily: "Syne, sans-serif",
            fontWeight: 800,
            fontSize: 22,
            color: "#fff",
            textAlign: "center",
          }}
        >
          No pude cerrar tu análisis
        </div>
        <div
          style={{
            fontFamily: "'DM Sans', sans-serif",
            fontSize: 14,
            color: "rgba(255,255,255,0.6)",
            textAlign: "center",
            maxWidth: 400,
            lineHeight: 1.5,
          }}
        >
          {evalError} {evalError?.startsWith("No pude guardar tu práctica")
            ? ""
            : "Tu práctica quedó guardada: al reintentar no pierdes nada."}
        </div>
        <button
          onClick={() => onRetryEvaluation?.()}
          style={{
            width: "100%",
            maxWidth: 400,
            height: 52,
            borderRadius: 99,
            border: "none",
            background: ORANGE,
            color: "var(--c-bg)",
            fontFamily: "Syne, sans-serif",
            fontWeight: 700,
            fontSize: 16,
            cursor: "pointer",
            boxShadow: "0 10px 30px -8px rgb(var(--c-primary-rgb) / 0.45)",
          }}
        >
          Reintentar análisis
        </button>
        <button
          onClick={() => setStep("transcript_only")}
          style={{
            width: "100%",
            maxWidth: 400,
            height: 48,
            borderRadius: 99,
            border: "1px solid rgba(255,255,255,0.18)",
            background: "transparent",
            color: "#fff",
            fontFamily: "Syne, sans-serif",
            fontWeight: 700,
            fontSize: 15,
            cursor: "pointer",
          }}
        >
          Ver mi conversación
        </button>
      </motion.div>
    );
  }

  if (step === "transcript_only") {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "1.2rem" }}
      >
        <div style={{ maxWidth: 560, margin: "0 auto", display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ fontFamily: "Syne, sans-serif", fontWeight: 800, fontSize: 20, color: "#fff" }}>
            Tu conversación
          </div>
          <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 13, color: "rgba(255,255,255,0.5)" }}>
            Sin análisis todavía. Puedes reintentarlo cuando quieras — la práctica está guardada.
          </div>
          <ConversationTranscript conversation={conversation} closerMsgs={closerMsgs} />
          <button
            onClick={() => onRetryEvaluation?.()}
            style={{
              width: "100%",
              height: 52,
              borderRadius: 99,
              border: "none",
              background: ORANGE,
              color: "var(--c-bg)",
              fontFamily: "Syne, sans-serif",
              fontWeight: 700,
              fontSize: 16,
              cursor: "pointer",
            }}
          >
            Reintentar análisis
          </button>
          {/* Salida SIEMPRE disponible. Antes, si el reintento también fallaba,
              el vendedor quedaba atrapado y tenía que cerrar la app. Ningún
              error debe dejar sin salida: la práctica ya está guardada. */}
          <button
            onClick={onLeaveWithoutEval}
            style={{
              width: "100%",
              height: 48,
              borderRadius: 99,
              border: "1px solid rgba(255,255,255,0.25)",
              background: "transparent",
              color: "rgba(255,255,255,0.75)",
              fontFamily: "Syne, sans-serif",
              fontWeight: 700,
              fontSize: 15,
              cursor: "pointer",
            }}
          >
            Volver al mapa
          </button>
        </div>
      </motion.div>
    );
  }

  // analyzing

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      style={{
        flex: 1,
        minHeight: 0,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: 24,
        padding: "1.2rem",
      }}
    >
      <style>{`
        @keyframes dot-pulse {
          0%, 100% { opacity: 0.3; transform: scale(0.8); }
          50% { opacity: 1; transform: scale(1); }
        }
      `}</style>
      <CloserCharacter size={96} state="motivation" />
      <div
        style={{
          fontFamily: "Syne, sans-serif",
          fontWeight: 700,
          fontSize: 22,
          color: "#fff",
          textAlign: "center",
        }}
      >
        Analizando tu práctica
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        {[0, 1, 2].map((i) => (
          <div
            key={i}
            style={{
              width: 8,
              height: 8,
              borderRadius: 99,
              background: ORANGE,
              animation: `dot-pulse 1s ease-in-out ${i * 0.2}s infinite`,
            }}
          />
        ))}
      </div>
      <AnimatePresence mode="wait">
        <motion.div
          key={slowNotice ? "slow" : msgIdx}
          initial={{ opacity: 0, y: 4 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -4 }}
          transition={{ duration: 0.3 }}
          style={{
            fontFamily: "'DM Sans', sans-serif",
            fontSize: 14,
            color: slowNotice ? "rgba(255,255,255,0.75)" : "rgba(255,255,255,0.5)",
            textAlign: "center",
            maxWidth: 400,
          }}
        >
          {slowNotice
            ? "Estoy revisando tu práctica con calma: puede tardar un par de minutos. No cierres la app."
            : mensajes[Math.min(msgIdx, mensajes.length - 1)]}

        </motion.div>
      </AnimatePresence>
    </motion.div>
  );
}


// ───────────────────────── EXIT DIALOG ─────────────────────────

function ExitDialog({
  onCancel,
  onConfirm,
}: {
  onCancel: () => void;
  onConfirm: () => void;
}) {
  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.7)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "1.2rem",
        zIndex: 100,
      }}
    >
      <div
        style={{
          background: "var(--c-surface)",
          borderRadius: 14,
          padding: 24,
          maxWidth: 360,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          gap: 20,
        }}
      >
        <div
          style={{
            fontFamily: "Syne, sans-serif",
            fontWeight: 700,
            fontSize: 18,
            color: "#fff",
            textAlign: "center",
          }}
        >
          ¿Salir de la práctica?
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <button
            onClick={onCancel}
            style={{
              flex: 1,
              height: 44,
              borderRadius: 99,
              background: "transparent",
              border: "1px solid rgba(255,255,255,0.4)",
              color: "#fff",
              fontFamily: "Syne, sans-serif",
              fontWeight: 700,
              fontSize: 14,
              cursor: "pointer",
            }}
          >
            Cancelar
          </button>
          <button
            onClick={onConfirm}
            style={{
              flex: 1,
              height: 44,
              borderRadius: 99,
              background: RED,
              border: "none",
              color: "#fff",
              fontFamily: "Syne, sans-serif",
              fontWeight: 700,
              fontSize: 14,
              cursor: "pointer",
            }}
          >
            Salir
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Etiqueta de un mensaje del asistente en el transcript.
 * El Actor habla como cliente; pero al cortar, Closer sale del personaje con el
 * mensaje de cierre del guion (phases.closing.message / message_incomplete),
 * que es determinista. Ese mensaje se firma como Closer, no como Cliente —
 * si no, parece que el cliente felicitó al vendedor por su técnica de ventas.
 */
function etiquetaAsistente(content: string, closerMsgs: Set<string>): "Closer" | "Cliente" {
  return closerMsgs.has((content ?? "").trim()) ? "Closer" : "Cliente";
}

function ConversationTranscript({
  conversation,
  closerMsgs = new Set<string>(),
}: {
  conversation: { role: string; content: string }[];
  closerMsgs?: Set<string>;
}) {
  const [open, setOpen] = useState(false);
  const items = conversation.filter(
    (m) => (m.role === "user" || m.role === "assistant") && m.content?.trim(),
  );
  if (items.length === 0) return null;

  return (
    <div style={{ width: "100%", textAlign: "left" }}>
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          width: "100%",
          height: 44,
          borderRadius: 99,
          border: "1px solid rgba(255,255,255,0.15)",
          background: "transparent",
          color: "rgba(255,255,255,0.85)",
          fontFamily: "Syne, sans-serif",
          fontWeight: 600,
          fontSize: 14,
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
        }}
      >
        {open ? "Ocultar conversación" : "Ver conversación completa"}
        <span style={{ fontSize: 12, opacity: 0.7 }}>{open ? "▲" : "▼"}</span>
      </button>

      {open && (
        <div
          style={{
            marginTop: 14,
            display: "flex",
            flexDirection: "column",
            gap: 10,
            padding: 14,
            borderRadius: 14,
            background: "rgba(255,255,255,0.04)",
            border: "1px solid rgba(255,255,255,0.08)",
            maxHeight: 360,
            overflowY: "auto",
          }}
        >
          {items.map((m, i) => {
            const isAgent = m.role === "assistant";
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 4,
                  alignItems: isAgent ? "flex-start" : "flex-end",
                }}
              >
                <div
                  style={{
                    fontFamily: "Syne, sans-serif",
                    fontSize: 11,
                    fontWeight: 700,
                    letterSpacing: 0.5,
                    textTransform: "uppercase",
                    color: isAgent ? ORANGE : "rgba(255,255,255,0.5)",
                  }}
                >
                  {isAgent ? etiquetaAsistente(m.content, closerMsgs) : "Tú"}
                </div>
                <div
                  style={{
                    maxWidth: "85%",
                    padding: "10px 14px",
                    borderRadius: 14,
                    background: isAgent
                      ? "rgb(var(--c-primary-rgb) / 0.12)"
                      : "rgba(255,255,255,0.08)",
                    color: "#fff",
                    fontFamily: "'DM Sans', sans-serif",
                    fontSize: 14,
                    lineHeight: 1.5,
                    whiteSpace: "pre-wrap",
                    wordBreak: "break-word",
                    textAlign: "left",
                  }}
                >
                  {m.content}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

